{"tool":"newFileCreated","path":"apps/kain-fabric-modeler/session/reducers.kn","content":"use session::session_schema

struct PlannedIntentRequest:
    intent_id: String
    reason: String

struct ReduceCommandResult:
    session: ModelerSessionDocument
    planned_intents: Array<PlannedIntentRequest>

fn mark_resource_invalidated(session: ModelerSessionDocument, resource_ref: String, reason: String) -> ModelerSessionDocument:
    if resource_ref == "":
        return session
    session.resources.invalidated_resource_refs = append_unique_string(session.resources.invalidated_resource_refs, resource_ref)
    let index = 0
    while index < len(session.resources.entries):
        if session.resources.entries[index].resource_ref == resource_ref:
            session.resources.entries[index].status = "dirty"
            session.resources.entries[index].dirty_reason = reason
        index = index + 1
    session.project.is_dirty = true
    return session

fn upsert_report_status(session: ModelerSessionDocument, report_ref: String, kind: String, producer: String, status: String, summary: String) -> ModelerSessionDocument:
    let index = 0
    while index < len(session.reports.entries):
        if session.reports.entries[index].report_ref == report_ref:
            session.reports.entries[index].status = status
            session.reports.entries[index].summary = summary
            session.reports.entries[index].producer = producer
            return session
        index = index + 1
    session.reports.entries.push(ReportEntry {
        report_ref: report_ref,
        kind: kind,
        producer: producer,
        status: status,
        version: 1,
        summary: summary,
        payload_ref: "",
        last_updated_at: "",
        last_updated_at: ""
    })
    return session

fn set_selection_summary(session: ModelerSessionDocument) -> ModelerSessionDocument:
    let entity_count = len(session.selection.entity_ids)
    if entity_count == 0:
        session.derived.selection_summary = "Nothing selected"
        return session
    session.derived.selection_summary = str(entity_count) + " entity selected"
    if entity_count != 1:
        session.derived.selection_summary = str(entity_count) + " entities selected"
    return session

fn set_active_tool_summary(session: ModelerSessionDocument) -> ModelerSessionDocument:
    session.derived.active_tool_summary = session.tooling.active_tool_id
    return session

fn push_checkpoint(session: ModelerSessionDocument, command: ModelerCommandEnvelope, label: String) -> ModelerSessionDocument:
    session.history.undo_stack.push(HistoryCheckpointEntry {
        checkpoint_id: "checkpoint:" + command.command_id,
        command_id: command.command_id,
        label: label,
        created_at: command.created_at
    })
    session.history.redo_stack = []
    session.derived.can_undo = len(session.history.undo_stack) > 0
    session.derived.can_redo = false
    return session

fn make_result(session: ModelerSessionDocument, planned_intents: Array<PlannedIntentRequest>) -> ReduceCommandResult:
    session.history.last_command_id = session.history.last_command_id
    session.derived.dirty_resource_count = len(session.resources.invalidated_resource_refs)
    session.derived.has_pending_jobs = len(session.jobs.active_jobs) > 0
    session = set_selection_summary(session)
    session = set_active_tool_summary(session)
    return ReduceCommandResult {
        session: session,
        planned_intents: planned_intents
    }

fn reduce_project_new(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let next = create_empty_modeler_session()
    next.project.project_id = command.command_id
    next.project.project_name = command_payload_value(command, "project_name")
    if next.project.project_name == "":
        next.project.project_name = "Untitled Modeler Project"
    next.project.project_root = "./projects/" + next.project.project_name
    let requested_mode = command_payload_value(command, "workspace_mode_id")
    if requested_mode != "":
        next.workspace.active_mode_id = requested_mode
    next.project.is_dirty = true
    next.history.last_command_id = command.command_id
    return make_result(next, [PlannedIntentRequest { intent_id: "project.bootstrap", reason: "Initialize a fresh project session." }])

fn reduce_project_save(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session.project.is_dirty = false
    session.history.last_command_id = command.command_id
    return make_result(session, [PlannedIntentRequest { intent_id: "project.persist", reason: "Persist current project state." }])

fn reduce_workspace_switch_mode(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let mode_id = command_payload_value(command, "mode_id")
    if mode_id != "":
        session.workspace.active_mode_id = mode_id
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_surface_focus(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let surface_id = command_payload_value(command, "surface_id")
    if surface_id != "":
        session.workspace.active_surface_id = surface_id
        session.workspace.expanded_surface_ids = append_unique_string(session.workspace.expanded_surface_ids, surface_id)
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_selection_set(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session.selection.entity_ids = parse_string_list(command_payload_value(command, "entity_ids"))
    session.selection.component_ids = parse_string_list(command_payload_value(command, "component_ids"))
    session.selection.selection_origin = command_payload_value(command, "selection_origin")
    if len(session.selection.entity_ids) > 0:
        session.selection.active_entity_id = session.selection.entity_ids[0]
    else:
        session.selection.active_entity_id = ""
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_selection_clear(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session.selection = SelectionState {
        entity_ids: [],
        component_ids: [],
        vertex_ids: [],
        edge_ids: [],
        face_ids: [],
        active_entity_id: "",
        selection_origin: ""
    }
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_tool_activate(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let tool_id = command_payload_value(command, "tool_id")
    if tool_id != "":
        session.tooling.active_tool_id = tool_id
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_tool_set_parameter(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let parameter_key = command_payload_value(command, "parameter_key")
    let parameter_value = command_payload_value(command, "parameter_value")
    if parameter_key == "brush_radius":
        session.tooling.active_tool_context.brush_radius = to_float_or(parameter_value, session.tooling.active_tool_context.brush_radius)
    if parameter_key == "brush_strength":
        session.tooling.active_tool_context.brush_strength = to_float_or(parameter_value, session.tooling.active_tool_context.brush_strength)
    if parameter_key == "brush_falloff":
        session.tooling.active_tool_context.brush_falloff = to_float_or(parameter_value, session.tooling.active_tool_context.brush_falloff)
    if parameter_key == "snapping_enabled":
        session.tooling.active_tool_context.snapping_enabled = to_bool_or(parameter_value, session.tooling.active_tool_context.snapping_enabled)
    if parameter_key == "transform_space":
        session.tooling.active_tool_context.transform_space = parameter_value
    if parameter_key == "pivot_mode":
        session.tooling.active_tool_context.pivot_mode = parameter_value
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_viewport_frame_selection(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session.viewport.frame_selection_requested = true
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_viewport_set_shading_mode(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let shading_mode = command_payload_value(command, "shading_mode")
    if shading_mode != "":
        session.viewport.shading_mode = shading_mode
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_mesh_seed_scene(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session = mark_resource_invalidated(session, "scene://main", "Scene seed requested.")
    session = mark_resource_invalidated(session, "buffer://preview/src", "Scene seed requested.")
    session = mark_resource_invalidated(session, "buffer://preview/dst", "Scene seed requested.")
    session = mark_resource_invalidated(session, "image://preview/current", "Scene seed requested.")
    session = upsert_report_status(session, "report://topology/current", "topology", "topology_analyzer", "stale", "Topology refresh required.")
    session = upsert_report_status(session, "report://publish/summary", "publish_summary", "node_publisher", "stale", "Publish summary refresh required.")
    session = push_checkpoint(session, command, "Seed Scene")
    session.history.last_command_id = command.command_id
    return make_result(session, [PlannedIntentRequest { intent_id: "project.bootstrap", reason: "Reseed active scene." }])

fn reduce_mesh_apply_brush(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let target_resource_ref = command_payload_value(command, "target_resource_ref")
    let mesh_ref = target_resource_ref
    if mesh_ref != "":
        session = mark_resource_invalidated(session, mesh_ref, "Brush stroke applied.")
    session = mark_resource_invalidated(session, "image://preview/current", "Brush stroke dirtied preview output.")
    session = mark_resource_invalidated(session, "buffer://preview/dst", "Brush stroke dirtied preview buffer.")
    session = upsert_report_status(session, "report://topology/current", "topology", "topology_analyzer", "stale", "Topology needs refresh after brush mutation.")
    session = upsert_report_status(session, "report://publish/summary", "publish_summary", "node_publisher", "stale", "Publish summary needs refresh after brush mutation.")
    session = push_checkpoint(session, command, "Apply Brush")
    session.history.last_command_id = command.command_id
    return make_result(session, [
        PlannedIntentRequest { intent_id: "mesh.brush_apply", reason: "Apply brush mutation through the native/runtime path." },
        PlannedIntentRequest { intent_id: "preview.rebake", reason: "Refresh preview after brush mutation." },
        PlannedIntentRequest { intent_id: "analysis.topology_refresh", reason: "Refresh topology after brush mutation." }
    ])

fn reduce_mesh_extrude_selection(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let target_resource_ref = command_payload_value(command, "target_resource_ref")
    if target_resource_ref != "":
        session = mark_resource_invalidated(session, target_resource_ref, "Extrude requested.")
    session = mark_resource_invalidated(session, "image://preview/current", "Extrude dirtied preview output.")
    session = upsert_report_status(session, "report://topology/current", "topology", "topology_analyzer", "stale", "Topology needs refresh after extrude.")
    session = upsert_report_status(session, "report://publish/summary", "publish_summary", "node_publisher", "stale", "Publish summary needs refresh after extrude.")
    session = push_checkpoint(session, command, "Extrude Selection")
    session.history.last_command_id = command.command_id
    return make_result(session, [
        PlannedIntentRequest { intent_id: "mesh.extrude_apply", reason: "Apply extrude operation." },
        PlannedIntentRequest { intent_id: "preview.rebake", reason: "Refresh preview after extrude." },
        PlannedIntentRequest { intent_id: "analysis.topology_refresh", reason: "Refresh topology after extrude." }
    ])

fn reduce_mesh_invalidate_preview(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let reason = command_payload_value(command, "reason")
    session = mark_resource_invalidated(session, "image://preview/current", reason)
    session = mark_resource_invalidated(session, "buffer://preview/dst", reason)
    session.derived.preview_status = "dirty"
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_preview_rebake(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session.derived.preview_status = "pending"
    session.history.last_command_id = command.command_id
    return make_result(session, [PlannedIntentRequest { intent_id: "preview.rebake", reason: "Explicit preview rebake requested." }])

fn reduce_analysis_refresh_topology(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session = upsert_report_status(session, "report://topology/current", "topology", "topology_analyzer", "pending", "Topology refresh running.")
    session.derived.topology_health = "pending"
    session.history.last_command_id = command.command_id
    return make_result(session, [PlannedIntentRequest { intent_id: "analysis.topology_refresh", reason: "Explicit topology refresh requested." }])

fn reduce_publish_refresh_summary(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session = upsert_report_status(session, "report://publish/summary", "publish_summary", "node_publisher", "pending", "Publish summary refresh running.")
    session.derived.publish_status = "pending"
    session.history.last_command_id = command.command_id
    return make_result(session, [PlannedIntentRequest { intent_id: "publish.summary_refresh", reason: "Explicit publish summary refresh requested." }])

fn reduce_job_fabric_completed(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    let intent_id = command_payload_value(command, "intent_id")
    let status = command_payload_value(command, "status")
    if intent_id == "preview.rebake" and status == "completed":
        session.derived.preview_status = "ready"
        session.resources.invalidated_resource_refs = remove_string(session.resources.invalidated_resource_refs, "image://preview/current")
        session.resources.invalidated_resource_refs = remove_string(session.resources.invalidated_resource_refs, "buffer://preview/dst")
    if intent_id == "analysis.topology_refresh" and status == "completed":
        session.derived.topology_health = "ready"
        session = upsert_report_status(session, "report://topology/current", "topology", "topology_analyzer", "ready", "Topology report refreshed.")
    if intent_id == "publish.summary_refresh" and status == "completed":
        session.derived.publish_status = "ready"
        session = upsert_report_status(session, "report://publish/summary", "publish_summary", "node_publisher", "ready", "Publish summary refreshed.")
    session.history.last_command_id = command.command_id
    return make_result(session, [])

fn reduce_history_undo(session: ModelerSessionDocument, command: ModelerCommandEnvelope) -> ReduceCommandResult:
    session.history.last_command_id = command.command_id
    return make_result(session, [PlannedIntentRequest { intent_id: "history.undo_apply", reason: "Undo last checkpointed modeling operation." }])

