{"tool":"newFileCreated","path":"apps/kain-fabric-modeler/session/intent_planner.kn","content":"use session::session_schema
use session::reducers

struct IntentPlanEntry:
    intent_id: String
    priority: Int
    reason: String

struct IntentPlanResult:
    entries: Array<IntentPlanEntry>

fn append_intent_plan(entries: Array<IntentPlanEntry>, intent_id: String, priority: Int, reason: String) -> Array<IntentPlanEntry>:
    let index = 0
    while index < len(entries):
        if entries[index].intent_id == intent_id:
            return entries
        index = index + 1
    entries.push(IntentPlanEntry {
        intent_id: intent_id,
        priority: priority,
        reason: reason
    })
    return entries

fn plan_from_reducer(result: ReduceCommandResult) -> IntentPlanResult:
    let entries = []
    let index = 0
    while index < len(result.planned_intents):
        let request = result.planned_intents[index]
        let priority = 50
        if request.intent_id == "project.bootstrap":
            priority = 10
        if request.intent_id == "mesh.brush_apply":
            priority = 20
        if request.intent_id == "mesh.extrude_apply":
            priority = 20
        if request.intent_id == "preview.rebake":
            priority = 30
        if request.intent_id == "analysis.topology_refresh":
            priority = 40
        if request.intent_id == "publish.summary_refresh":
            priority = 60
        entries.push(IntentPlanEntry {
            intent_id: request.intent_id,
            priority: priority,
            reason: request.reason
        })
        index = index + 1
    return IntentPlanResult { entries: entries }

fn plan_from_dirty_resources(session: ModelerSessionDocument, entries: Array<IntentPlanEntry>) -> Array<IntentPlanEntry>:
    let index = 0
    while index < len(session.resources.invalidated_resource_refs):
        let resource_ref = session.resources.invalidated_resource_refs[index]
        if resource_ref == "image://preview/current" or resource_ref == "buffer://preview/dst":
            entries = append_intent_plan(entries, "preview.rebake", 30, "Dirty preview resources require rebake.")
        if resource_ref == "mesh://active" or resource_ref == "scene://main":
            entries = append_intent_plan(entries, "analysis.topology_refresh", 40, "Dirty mesh/scene resources require topology refresh.")
            entries = append_intent_plan(entries, "publish.summary_refresh", 60, "Dirty mesh/scene resources require summary refresh.")
        index = index + 1
    return entries

fn plan_from_report_state(session: ModelerSessionDocument, entries: Array<IntentPlanEntry>) -> Array<IntentPlanEntry>:
    let index = 0
    while index < len(session.reports.entries):
        let report = session.reports.entries[index]
        if report.report_ref == "report://topology/current" and report.status == "stale":
            entries = append_intent_plan(entries, "analysis.topology_refresh", 40, "Stale topology report requires refresh.")
        if report.report_ref == "report://publish/summary" and report.status == "stale":
            entries = append_intent_plan(entries, "publish.summary_refresh", 60, "Stale publish summary requires refresh.")
        index = index + 1
    return entries

fn sort_plan_entries(entries: Array<IntentPlanEntry>) -> Array<IntentPlanEntry>:
    let outer = 0
    while outer < len(entries):
        let inner = outer + 1
        while inner < len(entries):
            if entries[inner].priority < entries[outer].priority:
                let temp = entries[outer]
                entries[outer] = entries[inner]
                entries[inner] = temp
            inner = inner + 1
        outer = outer + 1
    return entries

fn build_intent_plan(session: ModelerSessionDocument, reducer_result: ReduceCommandResult) -> IntentPlanResult:
    let plan = plan_from_reducer(reducer_result)
    let with_dirty = plan_from_dirty_resources(session, plan.entries)
    let with_reports = plan_from_report_state(session, with_dirty)
    return IntentPlanResult {
        entries: sort_plan_entries(with_reports)
    }
